-- Seeds the eight collections with every record of the former
-- code/frontend/src/data/<name>.json files, exactly as they were: the same
-- ids, every field's value, every list's order and the order of the records in
-- the file (seq follows that order).
--
-- Each statement reads the file's own JSON text for one collection: the
-- records are copied, not retyped, and jsonb_populate_record puts each key in
-- the column of the same name (a value of the wrong type stops the migration).
-- A key a record never had is a NULL column, which the API leaves out. A
-- single quote inside the text is doubled, as in any SQL literal.
--
-- The order is categories, products, reviews, gallery, team, services, faqs,
-- shop: a reference to a record that does not exist stops the whole file with
-- the database's own message and nothing is stored (the runner applies the
-- file in one transaction). ON CONFLICT DO NOTHING means a manual second run
-- never overwrites an edit the owner has made to a seeded record.

INSERT INTO categories ("id", "name", "line", "terrain", "_source")
SELECT r."id", r."name", r."line", r."terrain", r."_source"
FROM jsonb_array_elements('[
{"id":"hardtail","name":"Hardtail","line":"A suspension fork, a rigid back end: light, simple and the easiest to look after.","terrain":"Pass roads, gravel and your first trails","_source":"assumed"},
{"id":"cross-country","name":"Cross-country","line":"Light carbon bikes with short travel, built to climb fast and race.","terrain":"Long climbs, fast singletrack, race days","_source":"assumed"},
{"id":"trail","name":"Trail","line":"Suspension front and back for rock, roots and steep ground.","terrain":"Rough trails, broken roads, steep descents","_source":"assumed"},
{"id":"e-mtb","name":"E-MTB","line":"A motor that adds to your pedalling, for longer days and steeper climbs.","terrain":"Big days, high passes, the climbs you used to walk","_source":"assumed"}
]'::jsonb) WITH ORDINALITY AS e(doc, n),
     jsonb_populate_record(NULL::categories, e.doc) AS r
ORDER BY e.n
ON CONFLICT ("id") DO NOTHING;

INSERT INTO products ("id", "name", "brand", "category", "year", "price", "was", "price_listed", "fact", "status", "stock", "sizes", "sizes_out", "size_fit", "deal", "month", "wheel", "travel", "frame", "fork", "shock", "motor", "drivetrain", "brakes", "wheels", "tyres", "weight", "colour", "description", "ride", "rating", "review_count", "image", "image_back", "image_detail", "_source", "_invented")
SELECT r."id", r."name", r."brand", r."category", r."year", r."price", r."was", r."price_listed", r."fact", r."status", r."stock", r."sizes", r."sizes_out", r."size_fit", r."deal", r."month", r."wheel", r."travel", r."frame", r."fork", r."shock", r."motor", r."drivetrain", r."brakes", r."wheels", r."tyres", r."weight", r."colour", r."description", r."ride", r."rating", r."review_count", r."image", r."image_back", r."image_detail", r."_source", r."_invented"
FROM jsonb_array_elements('[
{"id":"talon-2","name":"Talon 2","brand":"Giant","category":"hardtail","year":2027,"price":18990000,"price_listed":"A$1,099 RRP","fact":"29 in · 100 mm fork · 1×9","status":"live","deal":true,"stock":9,"sizes":["XS","S","M","L","XL"],"sizes_out":[],"size_fit":["155–166 cm","163–172 cm","169–179 cm","176–186 cm","183–193 cm"],"wheel":"29","travel":"100 mm fork (80 mm on XS)","frame":"ALUXX-grade aluminium, 12×142 mm thru-axle, internal routing","fork":"SR Suntour SXC32-3 RL, coil spring, Boost 15×110 mm, lockout","shock":"None — hardtail","drivetrain":"microSHIFT Advent 1×9, 11–46T cassette, 30T ProWheel crank","brakes":"Tektro HD M3121 hydraulic, 180 / 160 mm rotors","wheels":"Giant alloy, double wall, tubeless compatible (27.5 in on XS and S)","tyres":"Maxxis Rekon Race 29 × 2.4 in","weight":"14.6 kg (size M)","colour":"Eclipse","rating":4.8,"review_count":52,"description":"The hardtail most riders start on: a light aluminium frame, a 100 mm fork and one chainring, so there is nothing to think about but the trail.","ride":"It climbs pass roads without fuss and stays calm on loose gravel. The 2.4 in Maxxis tyres grip more than the price suggests, and the 1×9 gearing is simple to keep clean. Ride it for a season, then add a dropper post when the trails get steeper.","image":"/images/ref/talon-2.jpg","image_back":"/images/ref/talon-2-drive.jpg","image_detail":"/images/ref/talon-2-front.jpg","_source":"web:https://www.giant-bicycles.com/au/talon-2","_invented":["weight","stock","rating","review_count","ride"]},
{"id":"talon-29-3","name":"Talon 29 3","brand":"Giant","category":"hardtail","year":2025,"price":13990000,"price_listed":"13.990.000 VND","fact":"29 in · 100 mm fork · 2×8","status":"live","deal":false,"stock":6,"sizes":["S","M"],"sizes_out":[],"size_fit":["160–172 cm","170–182 cm"],"wheel":"29","travel":"100 mm fork","frame":"ALUXX-grade aluminium, disc mounts","fork":"SR Suntour XCE, QR, steel steerer","shock":"None — hardtail","drivetrain":"Shimano Altus 2×8 shifters, Acera rear derailleur, 11–39T, 22/36 crank","brakes":"Tektro HDC M275 hydraulic disc","wheels":"Giant GX03V 29, double wall, 21 mm inner width","tyres":"Maxxis Ikon 29 × 2.2 in","weight":"15.1 kg (size M)","colour":"Frost Silver","rating":4.7,"review_count":38,"description":"The lowest-priced way onto a real mountain bike: hydraulic brakes, Maxxis tyres and two chainrings for the long climbs out of town.","ride":"Sixteen gears make long, steady climbs easy and the hydraulic brakes are calm on wet descents. It is the bike we suggest for riders who want to try dirt roads and passes before spending more.","image":"/images/ref/talon-29-3.jpg","_source":"web:https://xedap.vn/shop/xe-dap-dia-hinh-mtb-giant-talon-29-3-phanh-dia-banh-29-inches-2025","_invented":["size_fit","weight","stock","rating","review_count","ride"]},
{"id":"talon-29-1","name":"Talon 29 1","brand":"Giant","category":"hardtail","year":2025,"price":20490000,"was":23990000,"price_listed":"A$1,189 (was A$1,399)","fact":"29 in · 100 mm air fork · 1×10","status":"live","deal":false,"stock":4,"sizes":["S","M","L","XL"],"sizes_out":["XL"],"size_fit":["163–172 cm","169–179 cm","176–186 cm","183–193 cm"],"wheel":"29","travel":"100 mm fork","frame":"ALUXX-grade aluminium, thru-axle, internal routing","fork":"SR Suntour SXC32-2 RL, air spring, 100 mm, lockout","shock":"None — hardtail","drivetrain":"Shimano Deore 1×10, 11–51T cassette","brakes":"Tektro hydraulic disc, 180 / 160 mm rotors","wheels":"Giant alloy, tubeless ready","tyres":"Kenda Booster 29 × 2.4 in","weight":"14.2 kg (size M)","colour":"Charcoal","rating":4.7,"review_count":31,"description":"An air fork you can set to your weight and a wide-range Deore 1×10: the hardtail for riders who are already out every weekend.","ride":"The air fork is the difference you feel first — set it to your weight and the front end stops bouncing on rocky climbs. The 51-tooth cog gets you up the steep end of a pass seated.","image":"/images/ref/talon-29-1.jpg","image_back":"/images/ref/talon-29-1-drive.jpg","image_detail":"/images/ref/talon-29-1-front.jpg","_source":"web:https://www.giant-bicycles.com/au/bikes/mountain-bikes/trail","_invented":["brakes","weight","stock","rating","review_count","ride","size_fit"]},
{"id":"tempt-29-0","name":"Tempt 29 0","brand":"Liv","category":"hardtail","year":2027,"price":28990000,"price_listed":"A$1,699 RRP","fact":"29 in · 100 mm air fork · 1×12","status":"live","deal":false,"stock":3,"sizes":["XS","S","M","L"],"sizes_out":[],"size_fit":["150–160 cm","157–167 cm","165–175 cm","172–182 cm"],"wheel":"29","travel":"100 mm fork","frame":"ALUXX-grade aluminium, women''s geometry, dropper-ready","fork":"SR Suntour SXC32-2 RL, air spring, hydraulic lockout, 100 mm","shock":"None — hardtail","drivetrain":"Shimano Deore M6100 1×12, 10–51T, KMC X12 chain","brakes":"Shimano MT410 hydraulic, 180 / 160 mm rotors","wheels":"Giant alloy, tubeless ready","tyres":"Maxxis Rekon 29 × 2.4 in","weight":"13.8 kg (size S)","colour":"Stardust Grey","rating":4.8,"review_count":19,"description":"Liv''s best-equipped hardtail, shaped for women riders: a shorter reach, narrower bar and a saddle that fits, with twelve speeds and an air fork.","ride":"Riders who have struggled with a frame built for someone taller feel the difference in the first corner. Twelve speeds and a 51-tooth cog cover every climb we know.","image":"/images/ref/tempt-29-0.jpg","image_back":"/images/ref/tempt-29-0-drive.jpg","image_detail":"/images/ref/tempt-29-0-front.jpg","_source":"web:https://www.liv-cycling.com/au/bikes/mountain-bikes","_invented":["fork","drivetrain","brakes","tyres","weight","size_fit","stock","rating","review_count","ride"]},
{"id":"anthem-x-advanced-sl-3","name":"Anthem X Advanced SL 3","brand":"Giant","category":"cross-country","year":2026,"price":100990000,"was":125990000,"price_listed":"A$5,919 (was A$7,399)","fact":"29 in · 130 / 120 mm · carbon","status":"live","deal":false,"stock":2,"sizes":["S","M","L","XL"],"sizes_out":["S"],"size_fit":["160–170 cm","168–180 cm","177–188 cm","186–196 cm"],"wheel":"29","travel":"130 mm fork, 120 mm rear","frame":"Advanced SL-grade composite, 120 mm FlexPoint Pro, in-frame storage, adjustable geometry","fork":"Fox 34 Rhythm, 130 mm, Boost 15×110","shock":"Fox Float, 210 × 50 mm","drivetrain":"SRAM Eagle 90 Transmission 1×12, 10–52T","brakes":"Shimano Deore 4-piston hydraulic, 180 / 180 mm","wheels":"Giant XCT alloy, 29 in, tubeless","tyres":"Maxxis Rekon 29 × 2.4 in","weight":"12.4 kg (size M)","colour":"Raw Carbon","rating":4.9,"review_count":11,"description":"A carbon cross-country bike with a little more travel and a slacker head angle, for fast riders whose trails turn rough on the way down.","ride":"It pedals like a race bike — firm, quick and light up every climb — and the extra 10 mm up front lets you stay off the brakes on rocky descents. The frame''s storage hatch holds a tube and a pump.","image":"/images/ref/anthem-x-advanced-sl-3.jpg","image_back":"/images/ref/anthem-x-advanced-sl-3-drive.jpg","image_detail":"/images/ref/anthem-x-advanced-sl-3-front.jpg","_source":"web:https://www.giant-bicycles.com/au/bikes/mountain-bikes/cross-country","_invented":["fork","shock","drivetrain","brakes","wheels","tyres","weight","size_fit","stock","rating","review_count","ride"]},
{"id":"anthem-advanced-sl-0","name":"Anthem Advanced SL 0","brand":"Giant","category":"cross-country","year":2026,"price":254990000,"price_listed":"A$14,999 RRP","fact":"29 in · 120 mm · wireless 1×12","status":"live","deal":false,"stock":1,"sizes":["S","M","L","XL"],"sizes_out":["S","XL"],"size_fit":["160–170 cm","168–180 cm","177–188 cm","186–196 cm"],"wheel":"29","travel":"120 mm fork, 120 mm rear","frame":"Advanced SL-grade composite, 120 mm FlexPoint Pro, frame 1,530 g (M)","fork":"RockShox SID Ultimate 3P, 120 mm, Charger Race Day 2, remote lockout","shock":"RockShox SIDLuxe Ultimate, 210 × 50 mm, TwistLoc","drivetrain":"SRAM XX SL Eagle Transmission AXS 1×12, Quark power meter, 34T","brakes":"SRAM Motive Ultimate, 180 / 160 mm rotors","wheels":"Giant XCR carbon WheelSystem, carbon spokes","tyres":"Maxxis Aspen 29 × 2.4 in","weight":"About 10 kg (size M)","colour":"Raw Carbon","rating":5,"review_count":4,"description":"The bike of world-cup cross-country racing: a carbon frame, wireless shifting with a power meter and suspension locked from the bar.","ride":"At ten kilos it climbs as if the pass were half as long. It asks for a rider who races or trains with numbers — and for the shop to set it up with you, which we do as part of the sale.","image":"/images/ref/anthem-advanced-sl-0.jpg","image_back":"/images/ref/anthem-advanced-sl-0-drive.jpg","image_detail":"/images/ref/anthem-advanced-sl-0-front.jpg","_source":"web:https://www.giant-bicycles.com/au/bikes/mountain-bikes/cross-country","_invented":["tyres","weight","size_fit","stock","rating","review_count","ride"]},
{"id":"pique-advanced-sl-se","name":"Pique Advanced SL SE","brand":"Liv","category":"cross-country","year":2027,"price":322990000,"price_listed":"A$18,999 RRP","fact":"29 in · 120 mm · carbon race build","status":"live","deal":false,"stock":0,"sizes":["XS","S","M","L"],"sizes_out":["XS","S","M","L"],"size_fit":["150–160 cm","157–167 cm","165–176 cm","174–184 cm"],"wheel":"29","travel":"120 mm fork, 120 mm rear","frame":"Advanced SL-grade composite, women''s race geometry, 120 mm FlexPoint Pro","fork":"RockShox SID Ultimate, 120 mm, remote lockout","shock":"RockShox SIDLuxe Ultimate, 210 × 50 mm","drivetrain":"SRAM XX SL Eagle Transmission AXS 1×12","brakes":"SRAM Motive Ultimate, 180 / 160 mm rotors","wheels":"Giant XCR carbon WheelSystem","tyres":"Maxxis Aspen 29 × 2.4 in","weight":"About 9.9 kg (size S)","colour":"Stella Purple","rating":5,"review_count":3,"description":"Liv''s special-edition race bike: the lightest frame Liv makes, women''s geometry, and the best parts SRAM and RockShox build.","ride":"Made for one job — going uphill and through technical cross-country faster than anything else. We order each one for its rider; leave your details and we will call when the next one lands.","image":"/images/ref/pique-advanced-sl-se.jpg","image_back":"/images/ref/pique-advanced-sl-se-drive.jpg","image_detail":"/images/ref/pique-advanced-sl-se-front.jpg","_source":"web:https://www.liv-cycling.com/au/bikes/mountain-bikes","_invented":["fork","shock","drivetrain","brakes","wheels","tyres","weight","size_fit","stock","rating","review_count","ride"]},
{"id":"stance-0","name":"Stance 0","brand":"Giant","category":"trail","year":2027,"price":66490000,"price_listed":"A$3,899 RRP","fact":"29 in · 140 / 130 mm · 1×12","status":"live","deal":true,"stock":7,"sizes":["XS","S","M","L","XL"],"sizes_out":[],"size_fit":["152–163 cm","160–170 cm","168–180 cm","177–188 cm","186–196 cm"],"wheel":"29","travel":"140 mm fork, 130 mm rear","frame":"ALUXX-grade aluminium, 130 mm FlexPoint suspension, UDH, 12×148 mm","fork":"Giant STL 34 RC, dual air, 140 mm, Boost 15×110","shock":"Crest FloTrac Elite, 2-position lever, trunnion mount","drivetrain":"SRAM Eagle 90 Transmission 1×12, 10–52T, 30T crank","brakes":"TRP EVO Comp 4-piston hydraulic, 180 / 180 mm","wheels":"Giant TRA hookless alloy, 30 mm inner width (mixed 29/27.5 on XS)","tyres":"Maxxis Minion DHF 29 × 2.5 in front, Dissector 29 × 2.4 in rear","weight":"15.4 kg (size M)","colour":"Moonstone","rating":4.9,"review_count":23,"description":"A full-suspension trail bike at a hardtail rider''s budget: 130 mm at the back, a 140 mm air fork and a modern SRAM twelve-speed.","ride":"This is the bike for broken pass roads and rooty singletrack: the rear end keeps the tyre on the ground when a hardtail would skip. A 65.5° head angle makes it steady downhill without feeling heavy uphill.","image":"/images/ref/stance-0.jpg","image_back":"/images/ref/stance-0-drive.jpg","image_detail":"/images/ref/stance-0-front.jpg","_source":"web:https://www.giant-bicycles.com/au/bikes/mountain-bikes/trail","_invented":["tyres","weight","size_fit","stock","rating","review_count","ride"]},
{"id":"stance","name":"Stance","brand":"Giant","category":"trail","year":2026,"price":55990000,"price_listed":"A$3,299 RRP","fact":"29 in · 140 / 130 mm · 1×10","status":"live","deal":false,"stock":5,"sizes":["S","M","L","XL"],"sizes_out":["L"],"size_fit":["160–170 cm","168–180 cm","177–188 cm","186–196 cm"],"wheel":"29","travel":"140 mm fork, 130 mm rear","frame":"ALUXX aluminium, 130 mm FlexPoint suspension","fork":"SR Suntour Zeron35, air, 140 mm","shock":"Fox Float Rhythm, rebound, 210 × 52.5 mm","drivetrain":"Shimano CUES 1×10, 11–48T","brakes":"Tektro hydraulic disc, 180 / 180 mm","wheels":"Giant alloy, tubeless ready","tyres":"Maxxis Minion DHF 29 × 2.4 in","weight":"15.8 kg","colour":"Gloss Black","rating":4.7,"review_count":27,"description":"Giant''s entry-level dual-suspension bike, sitting between the Talon hardtail and the Trance X: 130 mm of travel and a Fox Rhythm shock.","ride":"The first full-suspension bike for most of our customers. The Shimano CUES drivetrain is hard-wearing and cheap to service, and the bike is happy on everything from gravel to the steep end of a trail.","image":"/images/ref/stance.jpg","image_back":"/images/ref/stance-drive.jpg","image_detail":"/images/ref/stance-front.jpg","_source":"web:https://flowmountainbike.com/tests/giant-stance-review/","_invented":["fork","tyres","colour","size_fit","stock","rating","review_count","ride"]},
{"id":"trance-x-1","name":"Trance X 1","brand":"Giant","category":"trail","year":2027,"price":93490000,"price_listed":"A$5,499 RRP","fact":"29 in · 150 / 140 mm · Fox 36","status":"live","deal":false,"month":true,"stock":3,"sizes":["S","M","L","XL"],"sizes_out":["XL"],"size_fit":["163–172 cm","171–180 cm","179–188 cm","187–196 cm"],"wheel":"29","travel":"150 mm fork, 140 mm rear","frame":"ALUXX SL aluminium, 140 mm Maestro, flip chips, in-frame storage","fork":"Fox 36 Float Performance, GRIP, 150 mm, Kabolt X axle","shock":"Fox Float Performance, 2-position, tuned for Giant","drivetrain":"SRAM Eagle 90 Transmission 1×12, 10–52T, 30T crank","brakes":"TRP EVO Expert 4-piston, 203 / 180 mm rotors","wheels":"Giant TRA hookless alloy, 30 mm inner width","tyres":"Maxxis Assegai 29 × 2.5 in front, Minion DHR II 29 × 2.4 in rear","weight":"15.2 kg (size M)","colour":"Black","rating":4.9,"review_count":17,"description":"Our favourite all-round trail bike: Maestro suspension, a Fox 36 and tyres that grip on wet rock, with geometry you can change with a flip chip.","ride":"It climbs on the firm setting and descends like a much bigger bike. Riders who bought it for weekend trails find it handles bike-park days too. The dropper drops up to 200 mm on the large sizes.","image":"/images/ref/trance-x-1.jpg","image_back":"/images/ref/trance-x-1-drive.jpg","image_detail":"/images/ref/trance-x-1-front.jpg","_source":"web:https://www.giant-bicycles.com/au/trance-x-29-2","_invented":["weight","stock","rating","review_count","ride"]},
{"id":"intrigue-x-2","name":"Intrigue X 2","brand":"Liv","category":"trail","year":2027,"price":76490000,"price_listed":"A$4,499 RRP","fact":"29 / 27.5 in · 150 / 140 mm · 1×12","status":"live","deal":false,"stock":4,"sizes":["XS","S","M","L"],"sizes_out":[],"size_fit":["150–160 cm","157–167 cm","165–176 cm","174–184 cm"],"wheel":"mixed","travel":"150 mm fork, 140 mm rear","frame":"ALUXX SL aluminium, 140 mm Maestro, women''s suspension tune","fork":"Fox 36 Rhythm, GRIP, 150 mm","shock":"Fox Float Rhythm, tuned for lighter riders","drivetrain":"Shimano Deore 1×12, 10–51T","brakes":"Shimano Deore 4-piston hydraulic, 203 / 180 mm","wheels":"Giant alloy, 29 in front, 27.5 in rear","tyres":"Maxxis Assegai 29 × 2.5 in front, Minion DHR II 27.5 × 2.4 in rear","weight":"15.6 kg (size S)","colour":"Morning Haze","rating":4.8,"review_count":9,"description":"Liv''s trail bike, with suspension tuned for lighter riders and a smaller rear wheel that makes it easy to move around under you.","ride":"Riders under 60 kg finally get suspension that moves on small roots instead of only big hits. The mixed wheels roll over rock at the front and turn quickly at the back.","image":"/images/ref/intrigue-x-2.jpg","image_back":"/images/ref/intrigue-x-2-drive.jpg","image_detail":"/images/ref/intrigue-x-2-front.jpg","_source":"web:https://www.liv-cycling.com/au/bikes/mountain-bikes","_invented":["fork","shock","drivetrain","brakes","tyres","weight","size_fit","stock","rating","review_count","ride"]},
{"id":"talon-e-plus-1","name":"Talon E+ 1","brand":"Giant","category":"e-mtb","year":2027,"price":84990000,"price_listed":"A$4,999 RRP","fact":"29 in · 500 Wh · 100 mm fork","status":"live","deal":true,"stock":5,"sizes":["S","M","L","XL"],"sizes_out":[],"size_fit":["160–170 cm","168–180 cm","177–188 cm","186–196 cm"],"wheel":"29","travel":"100 mm fork","frame":"ALUXX aluminium e-MTB hardtail, side-release battery","fork":"SR Suntour XCR 32 Air, 100 mm, lockout","shock":"None — hardtail","motor":"Giant SyncDrive Core, 60 Nm · EnergyPak 500 Wh, side release","drivetrain":"Shimano CUES 1×10, 11–48T","brakes":"Tektro 4-piston hydraulic, 203 / 180 mm","wheels":"Giant alloy, tubeless ready","tyres":"Maxxis Rekon 29 × 2.4 in","weight":"23.5 kg (size M)","colour":"Kelp Forest","rating":4.8,"review_count":14,"description":"An electric hardtail that makes a long pass a morning ride: a quiet Giant motor, a 500 Wh battery you lift out to charge at home.","ride":"The motor adds to what your legs give, up to 25 km/h, and the battery lasts a 60–80 km day in the middle setting. Riders use it for the climbs they used to walk.","image":"/images/ref/talon-e-plus-1.jpg","image_back":"/images/ref/talon-e-plus-1-drive.jpg","image_detail":"/images/ref/talon-e-plus-1-front.jpg","_source":"web:https://www.giant-bicycles.com/au/bikes/mountain-bikes/electric-mountain","_invented":["fork","motor","drivetrain","brakes","weight","size_fit","stock","rating","review_count","ride"]},
{"id":"tempt-e-plus-1","name":"Tempt E+ 1","brand":"Liv","category":"e-mtb","year":2027,"price":82990000,"price_listed":"A$4,999 RRP","fact":"29 / 27.5 in · integrated battery","status":"live","deal":false,"stock":0,"sizes":["XS","S","M"],"sizes_out":["XS","S","M"],"size_fit":["150–160 cm","157–167 cm","165–176 cm"],"wheel":"mixed","travel":"100 mm fork","frame":"ALUXX aluminium, women''s e-MTB geometry, integrated battery","fork":"SR Suntour XCR 32 Air, 100 mm","shock":"None — hardtail","motor":"Giant SyncDrive Core, 60 Nm · EnergyPak 500 Wh, integrated","drivetrain":"Shimano CUES 1×10","brakes":"Tektro 4-piston hydraulic","wheels":"Giant alloy, 29 in front, 27.5 in rear","tyres":"Maxxis Rekon 2.4 in","weight":"22.6 kg (size S)","colour":"Null White","rating":4.7,"review_count":6,"description":"Liv''s electric hardtail for women riders, with the battery hidden in the down tube and a smaller rear wheel for easy handling.","ride":"A light, low e-MTB that does not feel like a motorbike. This season''s bikes have sold — leave your details and we call you when the next ones arrive.","image":"/images/ref/tempt-e-plus-1.jpg","image_back":"/images/ref/tempt-e-plus-1-drive.jpg","image_detail":"/images/ref/tempt-e-plus-1-front.jpg","_source":"web:https://www.liv-cycling.com/au/bikes/mountain-bikes","_invented":["price","fork","motor","drivetrain","brakes","tyres","weight","size_fit","stock","rating","review_count","ride"]},
{"id":"embolden-e-plus-0","name":"Embolden E+ 0","brand":"Liv","category":"e-mtb","year":2027,"price":152990000,"price_listed":"A$8,999 RRP","fact":"29 in · 800 Wh · full suspension","status":"live","deal":false,"stock":2,"sizes":["XS","S","M","L"],"sizes_out":["XS"],"size_fit":["150–160 cm","157–167 cm","165–176 cm","174–184 cm"],"wheel":"29","travel":"150 mm fork, 140 mm rear","frame":"ALUXX SL aluminium, full suspension, integrated battery","fork":"Fox 36 Rhythm, 150 mm","shock":"Fox Float X, 140 mm","motor":"Giant SyncDrive Pro, 85 Nm · EnergyPak 800 Wh, integrated","drivetrain":"SRAM Eagle 90 Transmission 1×12","brakes":"SRAM Maven Base 4-piston, 220 / 203 mm","wheels":"Giant TRA alloy, tubeless","tyres":"Maxxis Assegai / Minion DHR II 29 × 2.5 in","weight":"24.8 kg (size S)","colour":"Atmosphere Black","rating":4.9,"review_count":5,"description":"A full-suspension electric trail bike with an 800 Wh battery — enough for a whole day in the mountains, two passes and back.","ride":"The strongest motor Giant makes and a battery big enough that range stops being the question. Riders take it where they would never have pedalled a bike before.","image":"/images/ref/embolden-e-plus-0.jpg","image_back":"/images/ref/embolden-e-plus-0-drive.jpg","image_detail":"/images/ref/embolden-e-plus-0-front.jpg","_source":"web:https://www.liv-cycling.com/au/bikes/mountain-bikes","_invented":["fork","shock","motor","drivetrain","brakes","wheels","tyres","weight","size_fit","stock","rating","review_count","ride"]}
]'::jsonb) WITH ORDINALITY AS e(doc, n),
     jsonb_populate_record(NULL::products, e.doc) AS r
ORDER BY e.n
ON CONFLICT ("id") DO NOTHING;

INSERT INTO reviews ("id", "name", "rating", "date", "bike", "text", "_source")
SELECT r."id", r."name", r."rating", r."date", r."bike", r."text", r."_source"
FROM jsonb_array_elements('[
{"id":"r-minh","name":"Minh","rating":5,"date":"2026-10-28","bike":"stance-0","text":"They set the Stance up for my height before I collected it. On broken road it feels twice as calm as my old hardtail.","_source":"assumed"},
{"id":"r-lan","name":"Lan","rating":5,"date":"2026-10-12","bike":"tempt-29-0","text":"Finally a frame that fits me. The fitting took an hour and they changed the bar and saddle without charging me.","_source":"assumed"},
{"id":"r-huy","name":"Huy","rating":5,"date":"2026-09-30","bike":"talon-2","text":"My first mountain bike. They called the same afternoon to check the size and delivered it built and adjusted.","_source":"assumed"},
{"id":"r-thao","name":"Thảo","rating":4,"date":"2026-09-14","bike":"talon-e-plus-1","text":"The battery does a long climb and back with charge left. The courier took four days, as promised, and a video call finished the build.","_source":"assumed"},
{"id":"r-quan","name":"Quân","rating":5,"date":"2026-08-22","bike":"trance-x-1","text":"Test-rode three bikes on their loop before choosing the Trance. No pressure, honest advice about which one I actually needed.","_source":"assumed"},
{"id":"r-ha","name":"Hà","rating":5,"date":"2026-08-03","bike":"intrigue-x-2","text":"They set the suspension for my weight and showed me how to check it. The first free service after six weeks was quick.","_source":"assumed"},
{"id":"r-tuan","name":"Tuấn","rating":5,"date":"2026-07-19","bike":"anthem-x-advanced-sl-3","text":"Ordered by message, paid by transfer, the bike arrived boxed and almost built. A video call talked me through the last steps.","_source":"assumed"},
{"id":"r-phuc","name":"Phúc","rating":4,"date":"2026-06-27","bike":"talon-29-3","text":"Good bike for the money. I would have liked the air fork, but they were honest that I did not need it yet.","_source":"assumed"},
{"id":"r-trang","name":"Trang","rating":5,"date":"2026-06-08","bike":"stance","text":"I came in for a tune-up and left knowing exactly what to replace next season. Kind, quick and fairly priced.","_source":"assumed"},
{"id":"r-khanh","name":"Khánh","rating":5,"date":"2026-05-21","bike":"talon-29-1","text":"Answered my questions at ten at night and had the bike ready the next morning. The 1×10 is so much simpler than my old triple.","_source":"assumed"},
{"id":"r-dung","name":"Dũng","rating":5,"date":"2026-04-30","bike":"embolden-e-plus-0","text":"Bought it for my wife after she tried it on the test loop. Now she waits for me at the top.","_source":"assumed"},
{"id":"r-vy","name":"Yến","rating":4,"date":"2026-04-11","bike":"stance-0","text":"Great bike and fair price. The size I wanted was gone, so they ordered it in and kept me posted every week.","_source":"assumed"}
]'::jsonb) WITH ORDINALITY AS e(doc, n),
     jsonb_populate_record(NULL::reviews, e.doc) AS r
ORDER BY e.n
ON CONFLICT ("id") DO NOTHING;

INSERT INTO gallery ("id", "image", "title", "caption", "type", "_source")
SELECT r."id", r."image", r."title", r."caption", r."type", r."_source"
FROM jsonb_array_elements('[
{"id":"pass-climb","image":"/images/gallery-pass-climb.jpg","title":"The long climb to the pass","caption":"Steady gears and a light bike matter more here than travel.","type":"hardtail","_source":"assumed"},
{"id":"rocky-descent","image":"/images/gallery-rocky-descent.jpg","title":"Rock on the way down","caption":"Where full suspension and a slack head angle earn their place.","type":"trail","_source":"assumed"},
{"id":"forest-singletrack","image":"/images/gallery-forest-singletrack.jpg","title":"Roots under the trees","caption":"Tight turns and grip on damp ground.","type":"trail","_source":"assumed"},
{"id":"group-ride","image":"/images/gallery-group-ride.jpg","title":"Laps at the pump track","caption":"Where many riders start: a short loop, a friend and no hurry.","type":"hardtail","_source":"assumed"},
{"id":"dirt-jump","image":"/images/gallery-dirt-jump.jpg","title":"Air off a rock ledge","caption":"A slack head angle and a dropper post make this feel possible.","type":"trail","_source":"assumed"},
{"id":"sunset-rest","image":"/images/gallery-sunset-rest.jpg","title":"A group day on e-MTBs","caption":"Mixed legs, one pace: the motor keeps everyone together on the climbs.","type":"e-mtb","_source":"assumed"},
{"id":"ridge-view","image":"/images/gallery-ridge-view.jpg","title":"Ridges above the valley","caption":"The kind of ground an e-MTB turns into a day ride.","type":"e-mtb","_source":"assumed"}
]'::jsonb) WITH ORDINALITY AS e(doc, n),
     jsonb_populate_record(NULL::gallery, e.doc) AS r
ORDER BY e.n
ON CONFLICT ("id") DO NOTHING;

INSERT INTO team ("id", "name", "role", "line", "rides", "_source")
SELECT r."id", r."name", r."role", r."line", r."rides", r."_source"
FROM jsonb_array_elements('[
{"id":"quang","name":"Quang","role":"Founder · bike fitting","line":"Opened the shop after ten years of riding the northern passes on bikes that did not fit.","rides":"Trail, hardtail","_source":"assumed"},
{"id":"thu","name":"Thu","role":"Workshop lead","line":"Builds every bike before it leaves and does the suspension and brake work.","rides":"Cross-country","_source":"assumed"},
{"id":"bao","name":"Bảo","role":"Advice and test rides","line":"Takes riders round the test loop and answers the messages that come in at night.","rides":"Trail, e-MTB","_source":"assumed"},
{"id":"van","name":"Vân","role":"Orders and delivery","line":"Calls every buyer to confirm size and delivery, and packs the bikes that travel by courier.","rides":"Hardtail","_source":"assumed"}
]'::jsonb) WITH ORDINALITY AS e(doc, n),
     jsonb_populate_record(NULL::team, e.doc) AS r
ORDER BY e.n
ON CONFLICT ("id") DO NOTHING;

INSERT INTO services ("id", "name", "line", "time", "price", "_source")
SELECT r."id", r."name", r."line", r."time", r."price", r."_source"
FROM jsonb_array_elements('[
{"id":"build","name":"Build and set-up of a new bike","line":"Assembled, brakes bled, gears indexed, suspension set to your weight.","time":"Included","price":0,"_source":"assumed"},
{"id":"fit","name":"Bike fit","line":"Saddle height and setback, bar, levers and cleats, on your bike.","time":"60 min","price":600000,"_source":"assumed"},
{"id":"service","name":"Full service","line":"Clean, check and adjust everything; bearings, cables and chain wear.","time":"1 day","price":450000,"_source":"assumed"},
{"id":"fork","name":"Fork lower service","line":"New oil and seals in the fork lowers.","time":"2 hours","price":650000,"_source":"assumed"},
{"id":"bleed","name":"Brake bleed","line":"Fresh fluid, firm lever, per brake.","time":"30 min","price":250000,"_source":"assumed"},
{"id":"tubeless","name":"Tubeless set-up","line":"Tape, valves and sealant for both wheels.","time":"45 min","price":200000,"_source":"assumed"}
]'::jsonb) WITH ORDINALITY AS e(doc, n),
     jsonb_populate_record(NULL::services, e.doc) AS r
ORDER BY e.n
ON CONFLICT ("id") DO NOTHING;

INSERT INTO faqs ("id", "q", "a", "_source")
SELECT r."id", r."q", r."a", r."_source"
FROM jsonb_array_elements('[
{"id":"size","q":"How do I know which frame size to choose?","a":"Each bike''s page shows the rider height for every size. Between two sizes, send us your height and inside-leg and we will tell you which, or book a test ride.","_source":"assumed"},
{"id":"first-bike","q":"Which bike for my first trails?","a":"A hardtail with a 100 mm fork and hydraulic brakes — the Talon 2 or Talon 29 3. Move to full suspension when the trails you ride get rough.","_source":"assumed"},
{"id":"test","q":"Can I try a bike before I buy it?","a":"Yes. Message us the bike and your size and we will have it ready on our test loop.","_source":"assumed"},
{"id":"delivery","q":"Do you deliver, and does it arrive built?","a":"In town we deliver free, fully built and set up. Elsewhere in Vietnam it travels by courier in a box, 90% built, with a video call to finish it.","_source":"assumed"},
{"id":"pay","q":"How can I pay?","a":"Bank transfer (we send a VietQR code when we confirm), cash on delivery in town, or card and cash at the shop.","_source":"assumed"},
{"id":"confirm","q":"When is my order final?","a":"We call within two hours of opening time to confirm size, stock and delivery. Nothing is charged before that call.","_source":"assumed"},
{"id":"warranty","q":"What warranty do the bikes have?","a":"Two years on the frame from the shop, on top of the maker''s own warranty, and parts for one year.","_source":"assumed"},
{"id":"service","q":"Is the first service free?","a":"Yes — within three months of buying, cables stretch and bolts settle, so bring the bike back and we adjust it free.","_source":"assumed"}
]'::jsonb) WITH ORDINALITY AS e(doc, n),
     jsonb_populate_record(NULL::faqs, e.doc) AS r
ORDER BY e.n
ON CONFLICT ("id") DO NOTHING;

INSERT INTO shop ("id", "founded", "bikes_built", "rating", "review_count", "reply_hours", "warranty_years", "free_service_months", "delivery_local", "delivery_nationwide", "delivery_fee", "pickup", "payment", "confirm", "stock_rule", "_source", "_invented")
SELECT r."id", r."founded", r."bikes_built", r."rating", r."review_count", r."reply_hours", r."warranty_years", r."free_service_months", r."delivery_local", r."delivery_nationwide", r."delivery_fee", r."pickup", r."payment", r."confirm", r."stock_rule", r."_source", r."_invented"
FROM jsonb_array_elements('[
{"id":"shop","founded":2016,"bikes_built":3200,"rating":4.9,"review_count":412,"reply_hours":2,"warranty_years":2,"free_service_months":3,"delivery_local":"Free, built and set up, in 1–2 days","delivery_nationwide":"By courier in a box, 90% built, in 3–5 days","delivery_fee":350000,"pickup":"Collect from the shop, built and fitted, the next day","payment":["Bank transfer (VietQR)","Cash on delivery (in town)","Card or cash at the shop"],"confirm":"We call within two hours of opening time to confirm the size, the stock and the delivery. Nothing is charged before that call.","stock_rule":"Each bike has a number in stock, kept by the shop. An order holds the bike until the confirming call; a size at zero shows as out of stock.","_source":"assumed","_invented":["founded","bikes_built","rating","review_count","reply_hours","warranty_years","free_service_months","delivery_local","delivery_nationwide","delivery_fee","pickup","payment","confirm","stock_rule"]}
]'::jsonb) WITH ORDINALITY AS e(doc, n),
     jsonb_populate_record(NULL::shop, e.doc) AS r
ORDER BY e.n
ON CONFLICT ("id") DO NOTHING;
